#!/usr/bin/env node
'use strict';

const fs = require('fs');
const path = require('path');

const VERSION = require('../package.json').version;

const STARTER_TEMPLATE = `// Starter Express Game Server powered by express-gamekit
const express = require('express');
const gamekit = require('express-gamekit');

const app = express();
const PORT = process.env.PORT || 3000;

// Mount express-gamekit at /game with optional apiKey protection
app.use('/game', gamekit({
  // apiKey: 'your-secret-api-key',
  modules: ['players', 'leaderboard', 'saves', 'matchmaking']
}));

app.get('/', (req, res) => {
  res.json({
    status: 'online',
    message: 'Express GameKit Server is running!',
    endpoints: {
      players: '/game/players',
      leaderboard: '/game/leaderboard',
      saves: '/game/saves',
      matchmaking: '/game/matchmaking'
    }
  });
});

app.listen(PORT, () => {
  console.log(\`🎮 Game server running at http://localhost:\${PORT}\`);
  console.log(\`⚡ Gamekit API available at http://localhost:\${PORT}/game\`);
});
`;

function showHelp() {
  console.log(`
express-gamekit v${VERSION}
Plug-and-play backend toolkit for web and multiplayer games.

Usage:
  npx express-gamekit <command> [options]

Commands:
  init            Generate a starter server.js file in current directory
  help            Show this help message

Options:
  --force         Overwrite server.js if it already exists
  --version, -v   Show current package version
`);
}

function handleInit(args) {
  const targetPath = path.resolve(process.cwd(), 'server.js');
  const force = args.includes('--force');

  if (fs.existsSync(targetPath) && !force) {
    console.error(`❌ Error: server.js already exists in ${process.cwd()}`);
    console.error('Use "npx express-gamekit init --force" to overwrite it.');
    process.exit(1);
  }

  fs.writeFileSync(targetPath, STARTER_TEMPLATE, 'utf8');
  console.log(`✨ Created starter game server: ${targetPath}`);
  console.log('\nNext steps:');
  console.log('  1. npm install express express-gamekit');
  console.log('  2. node server.js');
  console.log('  3. Open http://localhost:3000/ in your browser\n');
}

function main() {
  const args = process.argv.slice(2);
  const command = args[0];

  if (!command || command === 'help' || args.includes('--help') || args.includes('-h')) {
    showHelp();
    return;
  }

  if (command === '--version' || command === '-v') {
    console.log(`v${VERSION}`);
    return;
  }

  if (command === 'init') {
    handleInit(args.slice(1));
    return;
  }

  console.error(`Unknown command: "${command}"`);
  showHelp();
  process.exit(1);
}

main();
